        var primary=Path.Combine(Path.GetTempPath(),"aeroscience-primary-"+Guid.NewGuid().ToString("N"));var independent=Path.Combine(Path.GetTempPath(),"aeroscience-survivor-"+Guid.NewGuid().ToString("N"));var work=Path.Combine(f.Root,"restore-work");var configuration=Path.Combine(f.Root,"replacement-configuration");Directory.CreateDirectory(configuration);if(!OperatingSystem.IsWindows())File.SetUnixFileMode(configuration,UnixFileMode.UserRead|UnixFileMode.UserWrite|UnixFileMode.UserExecute);
        var firstKey=Path.Combine(f.Root,"first-key");var secondKey=Path.Combine(f.Root,"independent-key");File.WriteAllText(firstKey,Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32)));File.WriteAllText(secondKey,Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32)));OrganizationConfigurationTests.ProtectCredential(firstKey);OrganizationConfigurationTests.ProtectCredential(secondKey);
        var settings=f.Server.App.Services.GetRequiredService<OrganizationSettings>() with{StateDirectory=configuration};var options=new ServerOperationsOptions(true,primary,firstKey,"Disposable primary",work,System.Environment.GetEnvironmentVariable("AEROSCIENCE_RECOVERY_RESTIC")!,System.Environment.GetEnvironmentVariable("AEROSCIENCE_RECOVERY_PG_DUMP")!,System.Environment.GetEnvironmentVariable("AEROSCIENCE_RECOVERY_PG_RESTORE")!,System.Environment.GetEnvironmentVariable("AEROSCIENCE_ORG_TEST_DATABASE"),null,64*1024*1024,null,null){Independent=new(independent,secondKey,null,null,"auto")};
        string? restoredDatabase=null;string? recoveryWorkspace=null;
        string? applicationRole=null,recoveryRole=null;
        try{
