                await using(var root=new NpgsqlConnection(System.Environment.GetEnvironmentVariable("AEROSCIENCE_ORG_TEST_DATABASE"))){await root.OpenAsync();await using var setup=new NpgsqlCommand($"CREATE ROLE \"{applicationRole}\" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD '{applicationPassword}'; CREATE ROLE \"{recoveryRole}\" LOGIN NOSUPERUSER CREATEDB NOCREATEROLE PASSWORD '{recoveryPassword}'; GRANT \"{applicationRole}\" TO \"{recoveryRole}\" WITH INHERIT FALSE, SET TRUE; REVOKE ALL ON DATABASE \"{f.Database}\" FROM PUBLIC; GRANT CONNECT ON DATABASE \"{f.Database}\" TO \"{applicationRole}\"",root);await setup.ExecuteNonQueryAsync();}
                await using(var original=new NpgsqlConnection(settings.ConnectionString)){await original.OpenAsync();await using var grant=new NpgsqlCommand($"GRANT USAGE ON SCHEMA organization,public TO \"{applicationRole}\"; GRANT SELECT ON ALL TABLES IN SCHEMA organization,public TO \"{applicationRole}\"; GRANT SELECT ON ALL SEQUENCES IN SCHEMA organization,public TO \"{applicationRole}\"",original);await grant.ExecuteNonQueryAsync();}
                settings=settings with{ConnectionString=new NpgsqlConnectionStringBuilder(settings.ConnectionString){Username=applicationRole,Password=applicationPassword}.ConnectionString};options=options with{RecoveryConnectionString=new NpgsqlConnectionStringBuilder(options.RecoveryConnectionString){Username=recoveryRole,Password=recoveryPassword,Database="postgres"}.ConnectionString};
                await using var denied=new NpgsqlConnection(new NpgsqlConnectionStringBuilder(options.RecoveryConnectionString){Database=f.Database}.ConnectionString);var refused=await Assert.ThrowsAsync<PostgresException>(()=>denied.OpenAsync());Assert.Equal("42501",refused.SqlState);
            }
            ServerBackupRecord backup;Guid originalOrganization;string originalReceipt;
            using(var scope=f.Server.App.Services.CreateScope()){
                var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();originalOrganization=(await db.Organizations.SingleAsync()).PublicId;originalReceipt=(await db.Submissions.SingleAsync()).PayloadSha256;
                var destination=await db.DiscordDestinations.SingleAsync();db.DiscordDeliveries.Add(new(){Id=Guid.NewGuid(),EventId=Guid.NewGuid(),DestinationId=destination.PublicId,DestinationRevision=destination.Revision,State=NotificationState.Pending,CreatedUtc=DateTimeOffset.UtcNow,DueUtc=DateTimeOffset.UtcNow,Test=true});await db.SaveChangesAsync();
