                const string freshProtectionPassword="Different-Recovery-Workspace!Protection-2026";
                using(var key=RSA.Create(2048)){var certificateRequest=new CertificateRequest("CN=Fresh recovery workspace fixture",key,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);using var certificate=certificateRequest.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-1),DateTimeOffset.UtcNow.AddDays(1));File.WriteAllBytes(Path.Combine(f.Root,"recovery-identity.pfx"),certificate.Export(X509ContentType.Pfx,freshProtectionPassword));OrganizationConfigurationTests.ProtectCredential(Path.Combine(f.Root,"recovery-identity.pfx"));}
                var deployment=new Dictionary<string,string?>{["Organization:StateDirectory"]=configuration,["Organization:Operations:Enabled"]="true",["Organization:Operations:Repository"]=primary,["Organization:Operations:PasswordFile"]=firstKey,["Organization:Operations:WorkDirectory"]=work,["Organization:Operations:ResticExecutable"]=options.ResticExecutable,["Organization:Operations:PgDumpExecutable"]=options.PgDumpExecutable,["Organization:Operations:PgRestoreExecutable"]=options.PgRestoreExecutable,["Organization:Operations:RecoveryConnectionString"]=options.RecoveryConnectionString};
                deployment["Organization:KeyCertificatePassword"]=freshProtectionPassword;f.Server=await Start(recoveryWorkspace,f.Root,"Fresh Recovery Workspace",settingsOverride:deployment);Assert.NotEqual(origin,f.Server.Origin);await f.Server.App.Services.GetServices<IHostedService>().OfType<OrganizationOperationsWorker>().Single().StopAsync(default);
                var freshEnrollment=await f.Server.Post("/api/account-security/enroll",new AccountEnrollment("ResearchOnly!2026Flight"));var freshMfa=await f.Server.Post("/api/account-security/enable",new AccountCode(OrganizationServerTests.AuthenticatorCode(freshEnrollment.GetProperty("setupKey").GetString()!,DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30+1)));await f.Server.Post("/api/account-security/confirm-recovery",new AccountRecoveryConfirmation(freshMfa.GetProperty("recoveryCodes")[0].GetString()!));
                var kit=new OrganizationRecoveryKit(1,originalOrganization,origin,primary,File.ReadAllText(firstKey),null,null,null,"Synthetic independent recovery file"){Independent=new(independent,File.ReadAllText(secondKey),[],"auto"),RecoveryPoint=new(backup.Id,originalOrganization,backup.IndependentSnapshotId!,backup.BundleSha256,backup.CreatedUtc)};
                var command=new ImportRecoveryRequest(Guid.NewGuid(),"ResearchOnly!2026Flight",kit,true,true){UseLatestRecoveryPoint=true};var job=await f.Server.Post("/api/organization/operations/import-restore",command);var jobId=job.GetProperty("id").GetGuid();Assert.DoesNotContain(kit.Independent.RepositoryPassword,job.GetRawText());
                using(var scope=f.Server.App.Services.CreateScope()){var protectedJob=await scope.ServiceProvider.GetRequiredService<OrganizationDatabase>().ServerOperations.SingleAsync(j=>j.Id==jobId);Assert.NotNull(protectedJob.ProtectedImportJson);Assert.DoesNotContain(kit.Independent.RepositoryPassword,protectedJob.ProtectedImportJson!);}
                Assert.True(await OrganizationRecoveryEngine.ProcessOne(f.Server.App.Services,default));using(var scope=f.Server.App.Services.CreateScope()){var finished=await scope.ServiceProvider.GetRequiredService<OrganizationDatabase>().ServerOperations.SingleAsync(j=>j.Id==jobId);Assert.Equal(ServerOperationState.Completed,finished.State);Assert.Null(finished.ProtectedImportJson);}
                settings=f.Server.App.Services.GetRequiredService<OrganizationSettings>();
            }else{
