                var survivor=new OrganizationRecoveryEngine(emptyModel,settings,options with{Repository=independent,PasswordFile=secondKey,Independent=null});var recovered=await survivor.Discover(backup.IndependentSnapshotId!,default);Assert.Equal(backup.BundleSha256,recovered.BundleSha256);await survivor.VerifyRestore(recovered,default,stageReplacement:true,renewIdentity:renewIdentity);
                Assert.False(File.Exists(settings.KeyCertificateFile));
