            var candidate=OrganizationRecoveryActivation.Read(settings,false)!;restoredDatabase=candidate.Database;Assert.False(File.Exists(OrganizationRecoveryActivation.PathFor(settings,true)));Assert.Empty(Directory.GetFileSystemEntries(work));
            var originalManifest=JsonSerializer.Deserialize<ServerBackupManifest>(backup.ManifestJson,WireJson.Options)!;Assert.Equal(!(renewIdentity||guidedImport),candidate.CertificateSha256==originalManifest.CertificateSha256);
            // Activation refuses modified received evidence; an unverified copy cannot become live.
