            using(var staged=new OrganizationDatabase(new DbContextOptionsBuilder<OrganizationDatabase>().UseNpgsql(restoredConnection).Options)){
                Assert.Equal(originalOrganization,(await staged.Organizations.SingleAsync()).PublicId);Assert.Equal(originalReceipt,(await staged.Submissions.SingleAsync()).PayloadSha256);var restoredDestination=await staged.DiscordDestinations.SingleAsync();Assert.False(restoredDestination.Enabled);Assert.True(restoredDestination.Deleted);Assert.Empty(restoredDestination.ProtectedCredential);Assert.Equal(NotificationState.Ambiguous,(await staged.DiscordDeliveries.SingleAsync()).State);Assert.All(await staged.DeviceGrants.ToArrayAsync(),g=>Assert.True(g.Revoked));Assert.True((await staged.Users.SingleAsync(u=>u.TwoFactorEnabled)).TwoFactorEnabled);
                Assert.Equal(1,await staged.Memberships.CountAsync(m=>m.State==OrganizationMembershipState.Active));Assert.Equal(1,await staged.Memberships.CountAsync(m=>m.Role=="Pilot"&&m.State==OrganizationMembershipState.Suspended));Assert.All(await staged.Invitations.ToArrayAsync(),i=>Assert.NotNull(i.RevokedUtc));Assert.Equal(OrganizationEnrollmentMode.InvitationOnly,(await staged.EnrollmentPolicies.SingleAsync()).Mode);
                await staged.Submissions.ExecuteUpdateAsync(s=>s.SetProperty(v=>v.PayloadSha256,new string('0',64)));await Assert.ThrowsAsync<InvalidOperationException>(()=>OrganizationRecoveryActivation.Activate(settings,candidate.Id,default));Assert.False(File.Exists(OrganizationRecoveryActivation.PathFor(settings,true)));await staged.Submissions.ExecuteUpdateAsync(s=>s.SetProperty(v=>v.PayloadSha256,originalReceipt));
            }
